          "code": "import numpy as np\nfrom scipy.special import expit\nfrom sklearn.decomposition import TruncatedSVD\nfrom sklearn.ensemble import HistGradientBoostingClassifier\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import average_precision_score, log_loss, roc_auc_score\nfrom sklearn.model_selection import StratifiedKFold\n\nrng = np.random.default_rng(3212)\nn_tr, n_te = 800, 450\nn_tot = n_tr + n_te\nd_tab, d_emb, r_eff = 10, 384, 48\n\n# Dataset Hibrida Deteksi Listing Palsu Marketplace (10 Fitur Tabular Emas + 384D Embedding)\nX_tab = rng.normal(0.0, 1.0, size=(n_tot, d_tab))\nz_tab = (\n    2.10 * np.where(X_tab[:, 0] > 0.4, 1.3, -0.9)\n    + 1.80 * X_tab[:, 1] * X_tab[:, 2]\n    - 1.50 * np.abs(X_tab[:, 3])\n    + 1.25 * np.where(X_tab[:, 4] < -0.5, 1.4, -0.4)\n)\n\nZ_lat = rng.normal(0.0, 1.0, size=(n_tot, r_eff))\nQ, _ = np.linalg.qr(rng.normal(0.0, 1.0, size=(d_emb, r_eff)))\nE_raw = Z_lat @ Q.T + rng.normal(0.0, 0.14, size=(n_tot, d_emb))\nE_emb = E_raw / np.linalg.norm(E_raw, axis=1, keepdims=True)\nw_lat = rng.normal(0.0, 1.0, size=r_eff)\nw_lat = w_lat / np.linalg.norm(w_lat)\nz_sem = 17.5 * (E_emb @ (Q @ w_lat))\n\n# Interaksi silang modalitas: teks mencurigakan x akun penjual baru\nz_cross = 1.20 * np.maximum(z_sem, 0.0) * (X_tab[:, 0] > 0.3)\ny = rng.binomial(1, expit(-0.90 + 0.90 * z_tab + 0.95 * z_sem + z_cross))\n\nX_tab_tr, X_tab_te = X_tab[:n_tr], X_tab[n_tr:]\nE_tr, E_te = E_emb[:n_tr], E_emb[n_tr:]\ny_tr, y_te = y[:n_tr], y[n_tr:]\n\ndef eval_preds(label: str, n_feat: int, prob: np.ndarray) -> None:\n    auc = roc_auc_score(y_te, prob)\n    ap = average_precision_score(y_te, prob)\n    ll = log_loss(y_te, np.clip(prob, 1e-6, 1 - 1e-6))\n    print(f\"{label:42s} | Cols={n_feat:3d} | ROC-AUC={auc:.4f} | PR-AUC={ap:.4f} | LogLoss={ll:.4f}\")\n\n# 1. Tabular-Only HistGBDT\ngbdt_tab = HistGradientBoostingClassifier(max_depth=4, max_iter=40, max_bins=32, random_state=42)\ngbdt_tab.fit(X_tab_tr, y_tr)\np_tab = gbdt_tab.predict_proba(X_tab_te)[:, 1]\n\n# 2. Embedding-Only Linear Probe\nprobe_only = LogisticRegression(C=10.0, max_iter=250).fit(E_tr, y_tr)\np_emb = probe_only.predict_proba(E_te)[:, 1]\n\n# 3. ANTI-PATTERN: Naive Raw Concatenation [X_tab (10) + E_emb (384)] -> 394 Kolom ke GBDT!\ngbdt_raw = HistGradientBoostingClassifier(\n    max_depth=4, max_iter=40, max_bins=32, max_features=0.05, random_state=42\n)\ngbdt_raw.fit(np.hstack([X_tab_tr, E_tr]), y_tr)\np_raw = gbdt_raw.predict_proba(np.hstack([X_tab_te, E_te]))[:, 1]\n\n# 4. PRODUCTION-SAFE: Two-Stage Strict 5-Fold OOF Linear Probe + Fold-Safe SVD(8) + Tabular GBDT\nskf = StratifiedKFold(n_splits=5, shuffle=True, random_state=42)\noof_logit = np.empty(n_tr)\ntest_logits_folds = []\nfor tr_i, va_i in skf.split(E_tr, y_tr):\n    clf = LogisticRegression(C=10.0, max_iter=250).fit(E_tr[tr_i], y_tr[tr_i])\n    oof_logit[va_i] = clf.decision_function(E_tr[va_i])\n    test_logits_folds.append(clf.decision_function(E_te))\n\nsvd_fit = TruncatedSVD(n_components=8, random_state=42).fit(E_tr)\nX_fusion_tr = np.column_stack([X_tab_tr, oof_logit, svd_fit.transform(E_tr)])\nX_fusion_te = np.column_stack([X_tab_te, np.mean(test_logits_folds, axis=0), svd_fit.transform(E_te)])\n\ngbdt_fusion = HistGradientBoostingClassifier(max_depth=4, max_iter=40, max_bins=32, random_state=42)\ngbdt_fusion.fit(X_fusion_tr, y_tr)\np_fusion = gbdt_fusion.predict_proba(X_fusion_te)[:, 1]\n\nprint(f\"=== Benchmark Hybrid Fusion Deteksi Listing Palsu (Train={n_tr}, Test={n_te}, Pos={y_te.mean():.1%}) ===\")\neval_preds(\"1. Tabular-Only HistGBDT (10 emas)\", d_tab, p_tab)\neval_preds(\"2. Embedding-Only Linear Probe (384D)\", d_emb, p_emb)\neval_preds(\"3. Naive Raw Concat [Tab+384D] -> GBDT\", d_tab + d_emb, p_raw)\neval_preds(\"4. Two-Stage OOF Probe + SVD(8) -> GBDT\", X_fusion_tr.shape[1], p_fusion)",
