          "id": "code-ml-32-2-ch32_2_sklearn",
          "title": "Scikit-Learn 1.9: Komparasi MRL Prefix vs Non-MRL Slice vs PCA (k=32..256) pada Retrieval & Klasifikasi",
          "language": "python",
          "filename": "32_2_sklearn_mrl_vs_pca_retrieval_benchmark.py",
          "code": "import numpy as np\nfrom sklearn.decomposition import PCA\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import accuracy_score\nfrom sklearn.neighbors import NearestNeighbors\n\nrng = np.random.default_rng(3222)\nn_tr, n_te, D = 800, 400, 512\nn_tot = n_tr + n_te\n\ny = rng.integers(0, 5, size=n_tot)\ncenters = rng.normal(0.0, 0.52, size=(5, 48))\nZ_core = centers[y] + rng.normal(0.0, 1.0, size=(n_tot, 48))\nscales = (np.arange(1, D + 1, dtype=float)) ** (-0.60)\nE_mrl_raw = np.zeros((n_tot, D))\nE_mrl_raw[:, :48] = Z_core * scales[:48] * 4.0\nE_mrl_raw[:, 48:] = rng.normal(0.0, 1.0, size=(n_tot, D - 48)) * scales[48:]\n\ndef l2_norm(M: np.ndarray) -> np.ndarray:\n    return M / np.maximum(np.linalg.norm(M, axis=1, keepdims=True), 1e-12)\n\nE_mrl = l2_norm(E_mrl_raw)\nQ_rot, _ = np.linalg.qr(rng.normal(0.0, 1.0, size=(D, D)))\nE_legacy = E_mrl @ Q_rot\n\nE_mrl_tr, E_mrl_te = E_mrl[:n_tr], E_mrl[n_tr:]\nE_leg_tr, E_leg_te = E_legacy[:n_tr], E_legacy[n_tr:]\ny_tr, y_te = y[:n_tr], y[n_tr:]\n\nnn_gt = NearestNeighbors(n_neighbors=10, metric=\"cosine\").fit(E_leg_tr)\ngt_idx = nn_gt.kneighbors(E_leg_te[:120], return_distance=False)\n\ndef eval_space(X_tr_s: np.ndarray, X_te_s: np.ndarray) -> tuple[float, float]:\n    X_tr_n, X_te_n = l2_norm(X_tr_s), l2_norm(X_te_s)\n    nn = NearestNeighbors(n_neighbors=10, metric=\"cosine\").fit(X_tr_n)\n    pred = nn.kneighbors(X_te_n[:120], return_distance=False)\n    rec10 = float(np.mean([len(set(pred[i]).intersection(gt_idx[i])) / 10.0 for i in range(120)]))\n    clf = LogisticRegression(C=3.0, max_iter=250).fit(X_tr_n, y_tr)\n    acc = float(accuracy_score(y_te, clf.predict(X_te_n)))\n    return rec10, acc\n\nrec_full, acc_full = eval_space(E_leg_tr, E_leg_te)\nprint(f\"=== Komparasi Kompresi Embedding 512D -> k (Baseline 512D: R@10={rec_full:.2%}, Acc={acc_full:.2%}) ===\")\nfor k in [32, 64, 128, 256]:\n    r_mrl, a_mrl = eval_space(E_mrl_tr[:, :k], E_mrl_te[:, :k])\n    r_raw, a_raw = eval_space(E_leg_tr[:, :k], E_leg_te[:, :k])\n    pca = PCA(n_components=k, random_state=42).fit(E_leg_tr)\n    r_pca, a_pca = eval_space(pca.transform(E_leg_tr), pca.transform(E_leg_te))\n    evr = float(pca.explained_variance_ratio_.sum())\n    print(\n        f\"k={k:3d} | MRL Prefix: R@10={r_mrl:6.2%}, Acc={a_mrl:6.2%} \"\n        f\"| Non-MRL Slice: R@10={r_raw:6.2%}, Acc={a_raw:6.2%} \"\n        f\"| PCA({evr:4.0%} var): R@10={r_pca:6.2%}, Acc={a_pca:6.2%}\"\n    )",
          "expectedOutput": "=== Komparasi Kompresi Embedding 512D -> k (Baseline 512D: R@10=100.00%, Acc=98.00%) ===\nk= 32 | MRL Prefix: R@10=88.92%, Acc=95.00% | Non-MRL Slice: R@10=46.33%, Acc=94.25% | PCA( 93% var): R@10=86.75%, Acc=98.25%\nk= 64 | MRL Prefix: R@10=98.58%, Acc=98.00% | Non-MRL Slice: R@10=65.42%, Acc=97.25% | PCA( 99% var): R@10=90.25%, Acc=98.00%\nk=128 | MRL Prefix: R@10=99.08%, Acc=98.00% | Non-MRL Slice: R@10=74.83%, Acc=97.50% | PCA( 99% var): R@10=90.00%, Acc=98.00%\nk=256 | MRL Prefix: R@10=99.67%, Acc=98.00% | Non-MRL Slice: R@10=83.83%, Acc=98.25% | PCA(100% var): R@10=90.00%, Acc=98.00%",
          "actualOutput": "=== Komparasi Kompresi Embedding 512D -> k (Baseline 512D: R@10=100.00%, Acc=98.00%) ===\nk= 32 | MRL Prefix: R@10=88.92%, Acc=95.00% | Non-MRL Slice: R@10=46.33%, Acc=94.25% | PCA( 93% var): R@10=86.75%, Acc=98.25%\nk= 64 | MRL Prefix: R@10=98.58%, Acc=98.00% | Non-MRL Slice: R@10=65.42%, Acc=97.25% | PCA( 99% var): R@10=90.25%, Acc=98.00%\nk=128 | MRL Prefix: R@10=99.08%, Acc=98.00% | Non-MRL Slice: R@10=74.83%, Acc=97.50% | PCA( 99% var): R@10=90.00%, Acc=98.00%\nk=256 | MRL Prefix: R@10=99.67%, Acc=98.00% | Non-MRL Slice: R@10=83.83%, Acc=98.25% | PCA(100% var): R@10=90.00%, Acc=98.00%",
