          "solution": "```python\nimport numpy as np\n\ndef binary_quantize_and_rescore(E_db, E_q, k: int = 10, oversample: int = 4) -> tuple[float, float, float]:\n    E_db = np.asarray(E_db, dtype=np.float32)\n    E_q = np.asarray(E_q, dtype=np.float32)\n    E_db = E_db / np.maximum(np.linalg.norm(E_db, axis=1, keepdims=True), 1e-12)\n    E_q = E_q / np.maximum(np.linalg.norm(E_q, axis=1, keepdims=True), 1e-12)\n    gt = np.argsort(-(E_q @ E_db.T), axis=1)[:, :k]\n    mu = E_db.mean(axis=0, keepdims=True)\n    B_db = np.packbits((E_db > mu).astype(np.uint8), axis=1)\n    B_q = np.packbits((E_q > mu).astype(np.uint8), axis=1)\n    lut = np.array([bin(i).count('1') for i in range(256)], dtype=np.uint16)\n    ham = lut[np.bitwise_xor(B_q[:, None, :], B_db[None, :, :])].sum(axis=2)\n    top_bin = np.argsort(ham, axis=1)[:, :k]\n    rec_bin = float(np.mean([len(set(top_bin[i]).intersection(gt[i])) / k for i in range(len(gt))]))\n    top_ov = np.argsort(ham, axis=1)[:, :k * oversample]\n    rec_res = []\n    for i in range(len(gt)):\n        cands = top_ov[i]\n        rerank = cands[np.argsort(-(E_q[i] @ E_db[cands].T))[:k]]\n        rec_res.append(len(set(rerank).intersection(gt[i])) / k)\n    comp_ratio = float(E_db.nbytes / B_db.nbytes)\n    return (round(rec_bin, 4), round(float(np.mean(rec_res)), 4), round(comp_ratio, 1))\n```"
