          "code": "import numpy as np\nfrom scipy.optimize import minimize\n\nrng = np.random.default_rng(323)\nn_tr, n_te, d, K = 220, 800, 48, 4\n\nX_all = rng.normal(0.0, 1.0, size=(n_tr + n_te, d))\nW_true = rng.normal(0.0, 0.45, size=(d, K))\nW_true[:, 1] = 0.55 * W_true[:, 0] + rng.normal(0.0, 0.35, size=d)\nW_true[:, 3] = 0.55 * W_true[:, 2] + rng.normal(0.0, 0.35, size=d)\n\ndef softmax_temp(Z: np.ndarray, T: float = 1.0) -> np.ndarray:\n    Zs = Z / T\n    Zs = Zs - np.max(Zs, axis=1, keepdims=True)\n    eZ = np.exp(Zs)\n    return eZ / np.sum(eZ, axis=1, keepdims=True)\n\nZ_teacher_all = X_all @ W_true * 1.45\np_true_all = softmax_temp(Z_teacher_all, T=1.0)\ny_all = np.array([rng.choice(K, p=p_true_all[i]) for i in range(n_tr + n_te)])\n\nX_tr, X_te = X_all[:n_tr], X_all[n_tr:]\ny_tr, y_te = y_all[:n_tr], y_all[n_tr:]\nZt_tr, Zt_te = Z_teacher_all[:n_tr], Z_teacher_all[n_tr:]\ny_teacher_hard_tr = np.argmax(Zt_tr, axis=1)\nteacher_te_acc = float(np.mean(np.argmax(Zt_te, axis=1) == y_te))\n\nY_oh = np.eye(K)[y_tr]\n\ndef kd_loss_and_grad(w_flat: np.ndarray, X: np.ndarray, Y_hard: np.ndarray, Z_t: np.ndarray,\n                     T: float, alpha: float, lam: float, use_t2: bool = True) -> tuple[float, np.ndarray]:\n    W = w_flat.reshape(X.shape[1], K)\n    n = len(X)\n    Z_s = X @ W\n    q1 = softmax_temp(Z_s, 1.0)\n    qT = softmax_temp(Z_s, T)\n    pT = softmax_temp(Z_t, T)\n\n    ce_loss = -float(np.mean(np.sum(Y_hard * np.log(np.clip(q1, 1e-12, 1.0)), axis=1)))\n    kl_loss = float(np.mean(np.sum(pT * (np.log(np.clip(pT, 1e-12, 1.0)) - np.log(np.clip(qT, 1e-12, 1.0))), axis=1)))\n    scale_t = (T ** 2) if use_t2 else 1.0\n    reg = 0.5 * lam * float(np.sum(W ** 2))\n    loss = alpha * scale_t * kl_loss + (1.0 - alpha) * ce_loss + reg\n\n    grad_Z = alpha * (scale_t / T) * (qT - pT) / n + (1.0 - alpha) * (q1 - Y_hard) / n\n    grad_W = X.T @ grad_Z + lam * W\n    return loss, grad_W.ravel()\n\nw_chk = rng.normal(0.0, 0.1, size=d * K)\n_, g_ana = kd_loss_and_grad(w_chk, X_tr[:20], Y_oh[:20], Zt_tr[:20], T=3.0, alpha=0.85, lam=1e-2)\neps = 1e-6\ng_num = np.zeros_like(w_chk)\nfor j in range(12):\n    w_p, w_m = w_chk.copy(), w_chk.copy()\n    w_p[j] += eps\n    w_m[j] -= eps\n    g_num[j] = (\n        kd_loss_and_grad(w_p, X_tr[:20], Y_oh[:20], Zt_tr[:20], 3.0, 0.85, 1e-2)[0]\n        - kd_loss_and_grad(w_m, X_tr[:20], Y_oh[:20], Zt_tr[:20], 3.0, 0.85, 1e-2)[0]\n    ) / (2 * eps)\nmax_grad_err = float(np.max(np.abs(g_ana[:12] - g_num[:12])))\n\ndef train_student(Y_hard_in: np.ndarray, T: float, alpha: float, use_t2: bool = True) -> np.ndarray:\n    res = minimize(\n        kd_loss_and_grad, np.zeros(d * K),\n        args=(X_tr, Y_hard_in, Zt_tr, T, alpha, 0.015, use_t2),\n        jac=True, method=\"L-BFGS-B\", options={\"maxiter\": 120}\n    )\n    return res.x.reshape(d, K)\n\nprint(f\"=== Hinton (2015) Knowledge Distillation (N_transfer={n_tr}, d={d}, K={K}, Teacher Acc={teacher_te_acc:.2%}) ===\")\nprint(f\"Verifikasi Gradien Analitis vs Finite-Diff (12 param): Max Error = {max_grad_err:.2e}\")\nfor label, Yh, T_val, a_val, t2_flag in [\n    (\"1. Hard Ground-Truth Only (alpha=0.0)    \", Y_oh, 1.0, 0.00, True),\n    (\"2. Hard LLM Argmax Pseudo-Label Only     \", np.eye(K)[y_teacher_hard_tr], 1.0, 0.00, True),\n    (\"3. Soft KD BUG Tanpa T^2 (T=4, a=0.85)   \", Y_oh, 4.0, 0.85, False),\n    (\"4. Proper Hinton Soft KD + T^2 (T=4)     \", Y_oh, 4.0, 0.85, True),\n]:\n    W_s = train_student(Yh, T_val, a_val, t2_flag)\n    q_te = softmax_temp(X_te @ W_s, 1.0)\n    acc = float(np.mean(np.argmax(q_te, axis=1) == y_te))\n    fid = float(np.mean(np.argmax(q_te, axis=1) == np.argmax(Zt_te, axis=1)))\n    nll = -float(np.mean(np.log(np.clip(q_te[np.arange(n_te), y_te], 1e-12, 1.0))))\n    print(f\"{label} | Test Acc={acc:6.2%} | Teacher-Fidelity={fid:6.2%} | NLL={nll:.4f}\")",
          "expectedOutput": "=== Hinton (2015) Knowledge Distillation (N_transfer=220, d=48, K=4, Teacher Acc=81.12%) ===\nVerifikasi Gradien Analitis vs Finite-Diff (12 param): Max Error = 1.32e-09\n1. Hard Ground-Truth Only (alpha=0.0)     | Test Acc=64.88% | Teacher-Fidelity=72.88% | NLL=0.8116\n2. Hard LLM Argmax Pseudo-Label Only      | Test Acc=67.12% | Teacher-Fidelity=74.12% | NLL=0.7465\n3. Soft KD BUG Tanpa T^2 (T=4, a=0.85)    | Test Acc=71.75% | Teacher-Fidelity=81.88% | NLL=0.6865\n4. Proper Hinton Soft KD + T^2 (T=4)      | Test Acc=79.50% | Teacher-Fidelity=95.62% | NLL=0.5068",
          "actualOutput": "=== Hinton (2015) Knowledge Distillation (N_transfer=220, d=48, K=4, Teacher Acc=81.12%) ===\nVerifikasi Gradien Analitis vs Finite-Diff (12 param): Max Error = 1.32e-09\n1. Hard Ground-Truth Only (alpha=0.0)     | Test Acc=64.88% | Teacher-Fidelity=72.88% | NLL=0.8116\n2. Hard LLM Argmax Pseudo-Label Only      | Test Acc=67.12% | Teacher-Fidelity=74.12% | NLL=0.7465\n3. Soft KD BUG Tanpa T^2 (T=4, a=0.85)    | Test Acc=71.75% | Teacher-Fidelity=81.88% | NLL=0.6865\n4. Proper Hinton Soft KD + T^2 (T=4)      | Test Acc=79.50% | Teacher-Fidelity=95.62% | NLL=0.5068",
