          "solution": "```python\nimport numpy as np\n\ndef hinton_kd_step_metrics(X, Y_oh, Z_teacher, W_init, T: float = 4.0, alpha: float = 0.85, lr: float = 0.5) -> tuple[float, float, float, float]:\n    X = np.asarray(X, dtype=float)\n    Y_oh = np.asarray(Y_oh, dtype=float)\n    Z_t = np.asarray(Z_teacher, dtype=float)\n    W = np.asarray(W_init, dtype=float)\n    n = len(X)\n    def smax(Z, temp):\n        Zs = Z / temp\n        Zs = Zs - np.max(Zs, axis=1, keepdims=True)\n        e = np.exp(Zs)\n        return e / np.sum(e, axis=1, keepdims=True)\n    def loss_grad(Wm, use_t2: bool):\n        Zs = X @ Wm\n        q1, qT, pT = smax(Zs, 1.0), smax(Zs, T), smax(Z_t, T)\n        ce = -float(np.mean(np.sum(Y_oh * np.log(np.clip(q1, 1e-12, 1.0)), axis=1)))\n        kl = float(np.mean(np.sum(pT * (np.log(np.clip(pT, 1e-12, 1.0)) - np.log(np.clip(qT, 1e-12, 1.0))), axis=1)))\n        sc = (T ** 2) if use_t2 else 1.0\n        loss = alpha * sc * kl + (1.0 - alpha) * ce\n        gZ = alpha * (sc / T) * (qT - pT) / n + (1.0 - alpha) * (q1 - Y_oh) / n\n        return loss, X.T @ gZ\n    l0, g_t2 = loss_grad(W, True)\n    _, g_no = loss_grad(W, False)\n    l1, _ = loss_grad(W - lr * g_t2, True)\n    return (round(l0, 4), round(l1, 4), round(float(np.linalg.norm(g_t2)), 4), round(float(np.linalg.norm(g_no)), 4))\n```"
