          "code": "import numpy as np\nfrom sklearn.calibration import CalibratedClassifierCV\nfrom sklearn.ensemble import HistGradientBoostingClassifier\nfrom sklearn.metrics import accuracy_score\n\nrng = np.random.default_rng(3242)\nn_tr, n_id, n_ood, d = 900, 760, 90, 16\n\ncenters = rng.normal(0.0, 1.65, size=(3, d))\ny_tr = rng.integers(0, 3, size=n_tr)\nX_tr = centers[y_tr] + rng.normal(0.0, 1.35, size=(n_tr, d))\n\ny_id = rng.integers(0, 3, size=n_id)\nX_id = centers[y_id] + rng.normal(0.0, 1.35, size=(n_id, d))\n\ny_ood = rng.integers(0, 3, size=n_ood)\nood_shift = rng.normal(0.0, 3.2, size=(1, d))\nX_ood = ood_shift + rng.normal(0.0, 1.0, size=(n_ood, d))\n\nX_te = np.vstack([X_id, X_ood])\ny_te = np.concatenate([y_id, y_ood])\nis_ood = np.concatenate([np.zeros(n_id, dtype=bool), np.ones(n_ood, dtype=bool)])\n\nbase_gbdt = HistGradientBoostingClassifier(max_depth=4, max_iter=40, max_bins=32, random_state=42)\ngate_cal = CalibratedClassifierCV(base_gbdt, method=\"isotonic\", cv=3).fit(X_tr, y_tr)\nP1 = gate_cal.predict_proba(X_te)\ny1_pred = np.argmax(P1, axis=1)\n\nP1_sorted = np.sort(P1, axis=1)\nmargin = P1_sorted[:, -1] - P1_sorted[:, -2]\n\ndef l2_norm(M: np.ndarray) -> np.ndarray:\n    return M / np.maximum(np.linalg.norm(M, axis=1, keepdims=True), 1e-12)\n\ncentroids = l2_norm(np.vstack([X_tr[y_tr == k].mean(axis=0) for k in range(3)]))\nd_ood_tr = 1.0 - np.max(l2_norm(X_tr) @ centroids.T, axis=1)\ntau_ood = float(np.quantile(d_ood_tr, 0.96))\nd_ood_te = 1.0 - np.max(l2_norm(X_te) @ centroids.T, axis=1)\n\ny2_pred = y_te.copy()\nerr_id = rng.random(n_id) < 0.04\nerr_ood = rng.random(n_ood) < 0.07\ny2_pred[:n_id][err_id] = (y_te[:n_id][err_id] + 1) % 3\ny2_pred[n_id:][err_ood] = (y_te[n_id:][err_ood] + 1) % 3\n\nc1, c2, c_err = 0.000002, 0.0020, 0.045\n\ndef report_policy(label: str, esc_mask: np.ndarray) -> None:\n    y_sys = np.where(esc_mask, y2_pred, y1_pred)\n    acc_id = accuracy_score(y_te[~is_ood], y_sys[~is_ood])\n    acc_ood = accuracy_score(y_te[is_ood], y_sys[is_ood])\n    acc_all = accuracy_score(y_te, y_sys)\n    cloud_1m = float(np.mean(c1 + esc_mask * c2) * 1e6)\n    tot_1m = float(np.mean(c1 + esc_mask * c2 + (y_sys != y_te) * c_err) * 1e6)\n    print(\n        f\"{label:38s} | Esc={esc_mask.mean():5.1%} | ID={acc_id:6.2%} | OOD={acc_ood:6.2%} \"\n        f\"| All={acc_all:6.2%} | Cloud=${cloud_1m:5.0f}/1M | Total=${tot_1m:5.0f}/1M\"\n    )\n\nprint(f\"=== Hybrid Cascade Routing (N_test={len(y_te)}: {n_id} ID + {n_ood} OOD, tau_ood={tau_ood:.3f}) ===\")\nreport_policy(\"1. Tier-1 Classical Gate Only (0%)    \", np.zeros(len(y_te), dtype=bool))\nreport_policy(\"2. Tier-2 Foundation Only (100% LLM)  \", np.ones(len(y_te), dtype=bool))\nreport_policy(\"3. Margin Cascade Only (m < 0.45)     \", margin < 0.45)\nreport_policy(\"4. Margin + OOD Guardrail Cascade     \", (margin < 0.45) | (d_ood_te > tau_ood))",
