          "id": "code-ml-32-4-ch32_4_diag",
          "title": "Production Audit: Bencana Uncalibrated Overconfident Gate (ErrorCaught 36.9% -> 86.3%!) via Temperature Scaling",
          "language": "python",
          "filename": "32_4_cascade_gate_calibration_audit.py",
          "code": "import numpy as np\nfrom scipy.optimize import minimize\n\nrng = np.random.default_rng(3243)\nn_val, n_te, K = 600, 2000, 3\n\ndef smax(Z: np.ndarray, T: float = 1.0) -> np.ndarray:\n    Zs = Z / T\n    Zs -= Zs.max(axis=1, keepdims=True)\n    e = np.exp(Zs)\n    return e / e.sum(axis=1, keepdims=True)\n\nn_tot = n_val + n_te\nis_ambig = rng.random(n_tot) < 0.20\nZ_easy = rng.normal(0.0, 5.2, size=(n_tot, K))\nZ_hard = rng.normal(0.0, 1.1, size=(n_tot, K))\nZ_true_all = np.where(is_ambig[:, None], Z_hard, Z_easy)\nP_true_all = smax(Z_true_all, 1.0)\ny_all = np.array([rng.choice(K, p=P_true_all[i]) for i in range(n_tot)])\n\n# Simulasi model produksi overconfident (suhu terdistorsi 0.25x!)\nZ_overconf_all = Z_true_all / 0.25\nZ_val, Z_te = Z_overconf_all[:n_val], Z_overconf_all[n_val:]\ny_val, y_te = y_all[:n_val], y_all[n_val:]\n\nT_opt = float(minimize(\n    lambda t: -np.mean(np.log(np.clip(smax(Z_val, float(t[0]))[np.arange(n_val), y_val], 1e-12, 1.0))),\n    x0=[1.0], bounds=[(0.1, 10.0)]\n).x[0])\n\nP_uncal = smax(Z_te, 1.0)\nP_cal = smax(Z_te, T_opt)\ny1_pred = np.argmax(P_cal, axis=1)\nt1_errors = (y1_pred != y_te)\n\ny2_ok = rng.binomial(1, 0.980, size=n_te)\nt1_ok = (y1_pred == y_te).astype(int)\nc1, c2, c_err = 0.000002, 0.0020, 0.030\ntau_gate = 0.88\n\ndef ece_calc(y_t: np.ndarray, P: np.ndarray) -> float:\n    conf, pred = P.max(1), P.argmax(1)\n    edges = np.linspace(0, 1, 11)\n    return float(sum(\n        np.mean((conf > edges[b]) & (conf <= edges[b + 1])) *\n        abs(np.mean(pred[(conf > edges[b]) & (conf <= edges[b + 1])] == y_t[(conf > edges[b]) & (conf <= edges[b + 1])])\n            - np.mean(conf[(conf > edges[b]) & (conf <= edges[b + 1])]))\n        for b in range(10) if np.any((conf > edges[b]) & (conf <= edges[b + 1]))\n    ))\n\nprint(f\"=== Audit Kalibrasi Cascade Gate (N_test={n_te}, T_opt={T_opt:.3f}, Gate tau={tau_gate:.2f}) ===\")\nfor label, P in [\n    (\"1. Uncalibrated Overconfident Gate (T=1.0) \", P_uncal),\n    (\"2. Temperature-Calibrated Gate (T=T_opt)   \", P_cal),\n]:\n    esc = P.max(axis=1) < tau_gate\n    err_caught = float(np.sum(esc & t1_errors) / np.sum(t1_errors))\n    sys_acc = float(np.mean(np.where(esc, y2_ok, t1_ok)))\n    tot_cost_1m = float(np.mean(c1 + esc * c2 + (1 - np.where(esc, y2_ok, t1_ok)) * c_err) * 1e6)\n    print(\n        f\"{label} | ECE={ece_calc(y_te, P):.4f} | Esc={esc.mean():5.1%} \"\n        f\"| ErrorCaught={err_caught:5.1%} | SysAcc={sys_acc:6.2%} | TotalCost=${tot_cost_1m:5.0f}/1M\"\n    )",
          "expectedOutput": "=== Audit Kalibrasi Cascade Gate (N_test=2000, T_opt=3.287, Gate tau=0.88) ===\n1. Uncalibrated Overconfident Gate (T=1.0)  | ECE=0.1171 | Esc=12.8% | ErrorCaught=36.9% | SysAcc=89.30% | TotalCost=$ 3469/1M\n2. Temperature-Calibrated Gate (T=T_opt)    | ECE=0.0274 | Esc=38.1% | ErrorCaught=86.3% | SysAcc=97.10% | TotalCost=$ 1635/1M",
          "actualOutput": "=== Audit Kalibrasi Cascade Gate (N_test=2000, T_opt=3.287, Gate tau=0.88) ===\n1. Uncalibrated Overconfident Gate (T=1.0)  | ECE=0.1171 | Esc=12.8% | ErrorCaught=36.9% | SysAcc=89.30% | TotalCost=$ 3469/1M\n2. Temperature-Calibrated Gate (T=T_opt)    | ECE=0.0274 | Esc=38.1% | ErrorCaught=86.3% | SysAcc=97.10% | TotalCost=$ 1635/1M",
